def operation(key):
    """Return FastAPI route metadata for one documented operation."""
    tag, summary, description, errors = OPERATIONS[key]
    return {"tags":[tag],"summary":summary,"description":description,
            "responses":{code:{"description":message} for code,message in errors.items()}}
